<?php
chdir(dirname(__DIR__));require __DIR__.'/../vendor/autoload.php';$app=new \think\App();$app->initialize();$secret=trim((string)@file_get_contents((string)(getenv('LUMEN_INTEGRITY_KEY_FILE')?:'/www/server/lumenapi/integrity.key')));if($secret==='')exit(2);$now=date('Y-m-d H:i:s');$users=\think\facade\Db::name('users')->where('integrity_locked',0)->select()->toArray();foreach($users as $u){$payload=$u['id'].'|'.($u['quota_total']===null?'NULL':$u['quota_total']).'|'.$u['quota_used'];$sig=hash_hmac('sha256',$payload,$secret);if(empty($u['quota_integrity_hash'])||!hash_equals((string)$u['quota_integrity_hash'],$sig)){\think\facade\Db::name('users')->where('id',$u['id'])->update(['integrity_locked'=>1,'integrity_reason'=>'Watchdog：额度与可信签名不一致','integrity_locked_at'=>$now,'integrity_violation_count'=>\think\facade\Db::raw('integrity_violation_count + 1'),'status'=>0,'key_status'=>0,'updated_at'=>$now]);try{$r=\app\service\RedisService::connect();if($r){$r->setex('lumen:user:'.$u['id'].':integrity_locked',86400,'1');$r->publish('lumen:user:lock',(string)$u['id']);}}catch(\Throwable $e){} }}
